#!/usr/bin/env node
// Copies the non-TypeScript files of the package into dist/ next to the compiled files: the two stylesheets,
// tokens.json, the i18n manifest with its hints, and the shipped scripts (check-radix, check-tokens,
// build-i18n-manifest; bins of the package). i18n-keys.json is generated by `pnpm i18n:manifest` and committed; it is
// copied, not regenerated, so check-package can tell a stale manifest from a fresh one.
//
// Usage: node scripts/copy-assets.mjs   (scripts/build.mjs calls it after the emit)
import { copyFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const packageDir = resolve(join(dirname(fileURLToPath(import.meta.url)), '..'));

const ASSETS = [
  { from: 'src/theme.css', to: 'dist/theme.css' },
  { from: 'src/components.css', to: 'dist/components.css' },
  { from: 'tokens.json', to: 'dist/tokens.json' },
  { from: 'i18n-keys.json', to: 'dist/i18n-keys.json' },
  { from: 'i18n/hints.json', to: 'dist/i18n/hints.json' },
  { from: 'scripts/check-radix.mjs', to: 'dist/scripts/check-radix.mjs' },
  { from: 'scripts/check-tokens.mjs', to: 'dist/scripts/check-tokens.mjs' },
  { from: 'scripts/build-i18n-manifest.mjs', to: 'dist/scripts/build-i18n-manifest.mjs' },
  { from: 'scripts/check-contrast.mjs', to: 'dist/scripts/check-contrast.mjs' },
];

for (const asset of ASSETS) {
  const source = join(packageDir, asset.from);
  if (!existsSync(source)) {
    console.error(`copy-assets: missing ${asset.from}${asset.from === 'i18n-keys.json' ? ' (run `pnpm i18n:manifest`)' : ''}`);
    process.exit(1);
  }
  const target = join(packageDir, asset.to);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(source, target);
}
console.log(`copy-assets: ${ASSETS.length} file(s) into dist`);
